import {fabricWeight} from './supplier-fabric-data.js';
import {SUPPLIER_FABRICS,getSupplierFabric} from './supplier-fabric-data.js';
export function filterFabrics(items,{query='',collection='',family='',composition='',motif='',favoritesOnly=false,favorites=[]}={}){
 const q=query.trim().toLocaleLowerCase('fr');return items.filter(f=>(!motif||f.patternLabel===motif)&&(!collection||f.collection===collection)&&(!family||f.colorFamily===family)&&(!composition||f.compositionCode===composition)&&(!favoritesOnly||favorites.includes(f.id))&&(!q||`${f.reference} ${f.collection} ${f.supplier} ${f.colorName} ${f.patternLabel} ${f.compositionCode} ${f.weightValue}`.toLocaleLowerCase('fr').includes(q)));
}
export function mountSupplierFabrics({getConfig,update,notify,drawJacketSample}){
 const $=id=>document.getElementById(id);const host=$('supplier-grid');let limit=24,comparison=[];let favorites=[];try{favorites=JSON.parse(localStorage.getItem('atelier-fabric-favorites')||'[]').filter(id=>getSupplierFabric(id));}catch{}
 const picture=(f,className='supplier-picture')=>{const box=document.createElement('div');box.className=className;const img=document.createElement('img');img.src=f.image;img.alt=`${f.reference} · ${f.colorName} · ${f.patternLabel}`;img.loading='lazy';img.decoding='async';box.append(img);return box;};
 for(const [id,key,label] of [['supplier-family','colorFamily','Toutes les couleurs'],['supplier-collection','collection','Toutes les collections'],['supplier-motif','patternLabel','Tous les motifs'],['supplier-composition','compositionCode','Toutes les compositions']]){const select=$(id);const empty=document.createElement('option');empty.value='';empty.textContent=label;select.append(empty);for(const value of [...new Set(SUPPLIER_FABRICS.map(f=>f[key]))].sort()){const o=document.createElement('option');o.value=value;o.textContent=value;select.append(o);}select.addEventListener('change',()=>{limit=24;draw();});}
 const initialCollection=new URLSearchParams(location.search).get('collection');
 if(SUPPLIER_FABRICS.some(f=>f.collection===initialCollection))$('supplier-collection').value=initialCollection;
 function filtered(){return filterFabrics(SUPPLIER_FABRICS,{query:$('supplier-search').value,collection:$('supplier-collection').value,family:$('supplier-family').value,motif:$('supplier-motif').value,composition:$('supplier-composition').value,favoritesOnly:$('supplier-favorites-only').checked,favorites});}
 function draw(){const items=filtered();host.replaceChildren();$('supplier-count').textContent=`${items.length} tissu${items.length>1?'s':''}`;$('supplier-empty').hidden=items.length>0;$('supplier-more').hidden=items.length<=limit;
 for(const f of items.slice(0,limit)){const card=document.createElement('article');card.className='supplier-card';card.dataset.supplierCard=f.id;const choose=document.createElement('button');choose.className='supplier-pick';choose.type='button';choose.dataset.supplierPick=f.id;choose.setAttribute('aria-label',`Choisir le tissu ${f.reference}`);choose.append(picture(f));const ref=document.createElement('strong'),label=document.createElement('span'),weight=document.createElement('small');ref.textContent=f.reference;label.textContent=`${f.colorName} · ${f.patternLabel}`;weight.textContent=f.weightValue==null?f.collection:fabricWeight(f);choose.append(ref,label,weight);choose.addEventListener('click',()=>{update({supplierFabric:f.id});notify(`Tissu ${f.reference} sélectionné.`);});const actions=document.createElement('div');actions.className='supplier-actions';const detail=document.createElement('button');detail.textContent='Agrandir';detail.addEventListener('click',()=>showDetail(f));const star=document.createElement('button');star.textContent=favorites.includes(f.id)?'★':'☆';star.setAttribute('aria-label',`Favori ${f.reference}`);star.setAttribute('aria-pressed',String(favorites.includes(f.id)));star.addEventListener('click',()=>{favorites=favorites.includes(f.id)?favorites.filter(id=>id!==f.id):[...favorites,f.id];try{localStorage.setItem('atelier-fabric-favorites',JSON.stringify(favorites));}catch{}draw();});actions.append(detail,star);const compare=document.createElement('label');compare.className='supplier-compare-choice';const check=document.createElement('input');check.type='checkbox';check.checked=comparison.includes(f.id);check.addEventListener('change',()=>{if(check.checked&&comparison.length===3){check.checked=false;notify('Comparez jusqu’à trois tissus.');return;}comparison=check.checked?[...comparison,f.id]:comparison.filter(id=>id!==f.id);drawComparison();});compare.append(check,document.createTextNode('Comparer'));card.append(choose,actions,compare);host.append(card);}
 refresh();}
 function drawComparison(){const box=$('supplier-comparison');box.hidden=!comparison.length;box.replaceChildren();for(const id of comparison){const f=getSupplierFabric(id),item=document.createElement('div'),name=document.createElement('strong'),meta=document.createElement('p');name.textContent=f.reference;meta.textContent=`${f.colorName} · ${f.patternLabel} · ${fabricWeight(f)} · ${f.compositionCode}`;item.append(picture(f),name,meta);box.append(item);}}
 let sampleVersion=0;
 async function showDetail(f){const version=++sampleVersion;$('supplier-detail-image').src=f.image;$('supplier-detail-title').textContent=`${f.supplier} · ${f.reference}`;$('supplier-detail-meta').textContent=`${f.colorName} · ${f.patternLabel}\nCollection ${f.collection}\nComposition indiquée : ${f.compositionCode}\nPoids indiqué : ${fabricWeight(f)}`;$('supplier-detail-pick').onclick=()=>{update({supplierFabric:f.id});$('supplier-dialog').close();};$('supplier-dialog').showModal();
  const canvas=$('supplier-on-jacket'),ctx=canvas.getContext('2d');
  ctx.clearRect(0,0,canvas.width,canvas.height);
  $('fabric-render-status').textContent='Préparation du rendu…';
  try{
    const sample=await drawJacketSample(f.id);
    if(version!==sampleVersion)return;
    ctx.drawImage(sample,180,52,405,443,0,0,canvas.width,canvas.height);
    $('fabric-render-status').textContent='';
  }catch{
    if(version===sampleVersion)$('fabric-render-status').textContent='Le rendu de la veste est indisponible.';
  }
 }
 $('supplier-detail-close').addEventListener('click',()=>$('supplier-dialog').close());$('supplier-dialog').addEventListener('click',e=>{if(e.target===$('supplier-dialog'))$('supplier-dialog').close();});
 $('supplier-search').addEventListener('input',()=>{limit=24;draw();});$('supplier-favorites-only').addEventListener('change',draw);$('supplier-more').addEventListener('click',()=>{limit+=24;draw();});$('supplier-clear').addEventListener('click',()=>update({supplierFabric:null}));
 function refresh(){const selected=getSupplierFabric(getConfig().supplierFabric);$('supplier-selection').hidden=!selected;$('supplier-selection-name').textContent=selected?`Votre tissu : ${selected.supplier} ${selected.reference} · ${selected.colorName} · ${selected.patternLabel}`:'';for(const b of host.querySelectorAll('[data-supplier-pick]')){const active=b.dataset.supplierPick===selected?.id;b.setAttribute('aria-pressed',String(active));b.closest('article').classList.toggle('selected',active);}}
 draw();return {refresh};
}
